WHERE key = 'shop_bot_persona_bot_extras' AND deleted_at IS NULL;

UPDATE system_config SET value = replace(value,
  $P$- ขายเครื่องใหม่ + มือสองคัดสภาพ (มือสองเครื่องไทยประกันร้าน 60 วัน · มือสองเครื่องนอกประกันร้าน 30 วัน) · รับเทิร์น iPhone 12 ถึงรุ่นล่าสุด (รุ่นเก่ากว่านั้น tool จะไม่คืนราคาเทิร์น — ตอบว่า "รุ่นนี้ต้องให้ทีมดูเครื่องที่ร้านก่อนค่ะ" ห้ามเดาราคา)$P$,
  $P$- ขายเครื่องใหม่ + มือสองคัดสภาพ (มือสองประกันร้าน 60 วัน) · รับเทิร์น iPhone 12 ถึงรุ่นล่าสุด (รุ่นเก่ากว่านั้น tool จะไม่คืนราคาเทิร์น — ตอบว่า "รุ่นนี้ต้องให้ทีมดูเครื่องที่ร้านก่อนค่ะ" ห้ามเดาราคา)$P$),
    updated_at = NOW()
WHERE key = 'shop_bot_persona_base' AND deleted_at IS NULL;

-- ── KB ของโปร: ปิดเฉพาะแถวที่ apply สร้าง (id + intent ตรงทั้งคู่) — soft delete ตามกติกาฐานข้อมูล ──
UPDATE chat_knowledge_base SET active = false, deleted_at = NOW(), updated_at = NOW()
WHERE deleted_at IS NULL AND (id, intent) IN (('promo:imported-free-down','promo_imported_free_down'), ('faq:imported-device','imported_device_info'), ('faq:imported-tradein','imported_tradein'));

-- ── KB เดิม: คืนประโยคประกันมือสอง ──
UPDATE chat_knowledge_base
SET response_template = replace(response_template, $K$มือสองเครื่องไทยประกันร้าน 60 วัน
มือสองเครื่องนอกประกันร้าน 30 วันค่ะ$K$, $K$มือสองประกันร้าน 60 วันค่ะ$K$),
    updated_at = NOW()
WHERE intent = 'warranty_claim' AND deleted_at IS NULL
  AND response_template LIKE '%มือสองเครื่องนอกประกันร้าน 30 วันค่ะ%';

-- ── ผลตรวจ (✓ = กลับเหมือนก่อน apply ทุกตัวอักษร · △ = ถอยจุดของโปรครบ แต่ส่วนอื่นที่ถูกแก้หลัง apply ถูกคงไว้ · ✗ = ต้องดู) ──
SELECT CASE WHEN md5(value) = '1a25e223b8fd4604c1501e4caf20475e' THEN '✓ EXTRAS กลับเป็นข้อความก่อน apply ทุกตัวอักษร'
            WHEN position('ขั้น 3.5 — มือสอง: เครื่องนอก' in value) = 0 THEN '△ EXTRAS ถอยจุดของโปรครบ แต่ข้อความรวมไม่เท่าก่อน apply (ส่วนอื่นถูกแก้หลัง apply — คงไว้)'
            ELSE '✗ EXTRAS ยังมีขั้น 3.5' END || ' len=' || length(value) || ' (ก่อน apply 43904)' FROM system_config WHERE key='shop_bot_persona_bot_extras' AND deleted_at IS NULL;
SELECT CASE WHEN md5(value) = '058cd4ef96c4dc82e99b75715862f9dc' THEN '✓ BASE กลับเป็นข้อความก่อน apply ทุกตัวอักษร'
            WHEN position('มือสองเครื่องนอกประกันร้าน 30 วัน' in value) = 0 THEN '△ BASE ถอยจุดของโปรครบ แต่ข้อความรวมไม่เท่าก่อน apply (ส่วนอื่นถูกแก้หลัง apply — คงไว้)'
            ELSE '✗ BASE ยังมีประโยคเครื่องนอก 30 วัน' END || ' len=' || length(value) || ' (ก่อน apply 10471)' FROM system_config WHERE key='shop_bot_persona_base' AND deleted_at IS NULL;
SELECT CASE WHEN count(*) = 0 THEN '✓' ELSE '✗' END || ' KB ของโปรที่ยังเปิดอยู่ ' || count(*) || ' แถว (คาด 0)' FROM chat_knowledge_base WHERE (id, intent) IN (('promo:imported-free-down','promo_imported_free_down'), ('faq:imported-device','imported_device_info'), ('faq:imported-tradein','imported_tradein')) AND deleted_at IS NULL;
SELECT CASE WHEN response_template LIKE '%มือสองประกันร้าน 60 วันค่ะ%' AND response_template NOT LIKE '%เครื่องนอก%' THEN '✓' ELSE '✗' END || ' KB warranty_claim กลับเป็นประโยคเดิม' FROM chat_knowledge_base WHERE intent='warranty_claim' AND deleted_at IS NULL;

COMMIT;
